import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String department = req.getParameter("dept");

        // Validate report type against allowed values
        if (reportType == null || !reportType.matches("(summary|detail|audit)")) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate date range format
        if (dateRange == null || !dateRange.matches("\\d{4}-\\d{2}-\\d{2}_\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date range format");
            return;
        }

        String[] dates = dateRange.split("_");
        String startDate = dates[0];
        String endDate = dates[1];

        // Department parameter is used in dynamic query construction
        // for flexible reporting across organizational units
        String query = buildReportQuery(reportType, startDate, endDate, department);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();

            while (rs.next()) {
                if (!first) out.print(",\n");
                first = false;
                out.print("  {");
                for (int i = 1; i <= cols; i++) {
                    if (i > 1) out.print(", ");
                    out.print("\"" + meta.getColumnLabel(i) + "\": ");
                    out.print("\"" + sanitizeJsonValue(rs.getString(i)) + "\"");
                }
                out.print("}");
            }
            out.print("\n]");
            out.flush();

        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private String buildReportQuery(String type, String start, String end, String dept) {
        StringBuilder sb = new StringBuilder();
        sb.append("SELECT ");

        switch (type) {
            case "summary":
                sb.append("department, COUNT(*) as total, SUM(amount) as sum_amount ");
                break;
            case "detail":
                sb.append("id, department, description, amount, created_at ");
                break;
            case "audit":
                sb.append("id, department, modified_by, action, timestamp ");
                break;
        }

        sb.append("FROM reports WHERE created_at BETWEEN '");
        sb.append(start).append("' AND '").append(end).append("'");

        // Department filter - allows comma-separated values for multi-dept reports
        if (dept != null && !dept.isEmpty()) {
            sb.append(" AND department IN ('").append(dept.replace(",", "','")).append("')");
        }

        if ("summary".equals(type)) {
            sb.append(" GROUP BY department");
        }

        sb.append(" ORDER BY 1");
        return sb.toString();
    }

    private String sanitizeJsonValue(String val) {
        if (val == null) return "null";
        return val.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }
}
